#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_1_event(q: &dyn Query, asker: &Asker, event: &Event) -> Option<Fired> { if let Event::ZoneChange { old, new, from, to, .. } = event { let id = *new; let subject = Target::Object(id); let data = [0u32, u32::MAX]; if to.is(ZoneKind::Battlefield) && Some(asker.source) == Some(id) { return Some(Fired { subject, data }); } }
 None }
fn color_pair_of(q: &dyn Query, id: ObjectId) -> Option<ColorSet> { let colors = q.chars(id).colors; (colors.iter().count() == 2).then_some(colors) }
fn one_of_each_color_pair(q: &dyn Query, choice: &Choice, _: u32) -> Verdict { let used: Vec<Option<ColorSet>> = choice.selected.iter().map(|&c| color_pair_of(q, c)).collect(); let complete = used.iter().enumerate().all(|(i, k)| k.is_some() && !used[..i].contains(k)); Verdict { complete, addable: Bits::of(choice.candidates.len(), |i| { let k = color_pair_of(q, choice.candidates[i]); k.is_some() && !used.contains(&k) }) } }
fn ability_1(g: &mut dyn Game, item: &StackItem) -> Result<(), Suspend> { let asker = &Asker::new(item.object, item.controller);
let objects_0 = { let q: &dyn Query = g; (((Some(asker.controller).into_iter().collect::<Vec<PlayerId>>()).into_iter().flat_map(|p: PlayerId| q.state().zone(Zone::library(p)).to_vec()).collect::<Vec<ObjectId>>()).into_iter().filter(|&id| true && true).collect::<Vec<ObjectId>>()).into_iter().take((10i64).max(0) as usize).collect::<Vec<ObjectId>>() }; let mut owners_0: Vec<PlayerId> = objects_0.iter().map(|o| g.state().obj(*o).owner).collect(); owners_0.dedup(); for owner in owners_0 { let cards: Vec<ObjectId> = objects_0.iter().copied().filter(|o| g.state().obj(*o).owner == owner).collect(); g.reveal(owner, &cards); }
let player_1 = { let q: &dyn Query = g; Some(asker.controller).expect("a reference that always names a player") }; let pool_1 = { let q: &dyn Query = g; (objects_0.clone()).into_iter().filter(|&id| q.state().obj(id).became.is_none() && q.state().obj(id).zone.kind() == ZoneKind::Library).collect::<Vec<ObjectId>>() }; let count_1 = { let q: &dyn Query = g; cantrip_mechanics::select::Count::AsManyAsCan((10i64).max(0) as u32) }; let picked_1 = cantrip_mechanics::choose::select(g, player_1, asker.source, Purpose::PutIntoHand, pool_1, cantrip_mechanics::select::Selection::of(count_1, &[]).with(cantrip_api::select::part(&(one_of_each_color_pair as SelectFn), 0, "one for each color pair")))?;
let objects_2 = { let q: &dyn Query = g; picked_1.clone() }; let moved_2 = g.return_to_hand_revealed(&objects_2);
let library_3 = { let q: &dyn Query = g; Some(asker.controller).expect("a reference that always names a player") }; let cards_3: Vec<ObjectId> = { let q: &dyn Query = g; ({ let without: Vec<ObjectId> = { let mut all: Vec<ObjectId> = Vec::new(); for id in objects_2.iter().copied().filter(|&o| q.state().obj(o).became.is_some()).collect::<Vec<ObjectId>>() { if !all.contains(&id) { all.push(id); } } all }; (objects_0.clone()).into_iter().filter(|id| !without.contains(id)).collect::<Vec<ObjectId>>() }).into_iter().filter(|&id| q.state().obj(id).became.is_none() && q.state().obj(id).zone.kind() == ZoneKind::Library).collect::<Vec<ObjectId>>() }.into_iter().filter(|&o| g.state().obj(o).became.is_none() && g.state().obj(o).zone == Zone::library(library_3)).collect(); let placed_3 = cards_3.clone();
g.bottom_in_random_order(library_3, &cards_3);
g.end_sentence();
 Ok(()) }

